rule.example:
# WRONG: engine imports concrete implementation
from engines.llm.mistral_adapter import MistralAdapter
class DialogueHandler:
    def __init__(self):
        self.llm = MistralAdapter()

# RIGHT: engine depends on protocol, concrete injected by caller
from engines.llm.protocols import LLMClientProtocol
class DialogueHandler:
    def __init__(self, llm: LLMClientProtocol, db: AsyncSession):
        self.llm = llm
        self.db = db

from typing import Literal
class Action(BaseModel):
    type: Literal["speak","gesture","move","attack","give_item","none"]
